   991  // ------------------------------------------------------------------------------------------------
   992  std::string XFileParser::GetNextToken() {
   993      std::string s;
   994
   995      // process binary-formatted file
   996      if (mIsBinaryFormat) {
   997          // in binary mode it will only return NAME and STRING token
   998          // and (correctly) skip over other tokens.
   999          if (mEnd - mP < 2) {
  1000              return s;
  1001          }
  1002          unsigned int tok = ReadBinWord();
  1003          unsigned int len;
  1004
  1005          // standalone tokens
  1006          switch (tok) {
  1007          case 1: {
  1008              // name token
  1009              if (mEnd - mP < 4) {
  1010                  return s;
  1011              }
  1012              len = ReadBinDWord();
  1013              const int bounds = int(mEnd - mP);
  1014              const int iLen = int(len);
  1015              if (iLen < 0) {
  1016                  return s;
  1017              }
  1018              if (bounds < iLen) {
  1019                  return s;
  1020              }
  1021              s = std::string(mP, len);
  1022              mP += len;
  1023          }
  1024              return s;
  1025
  1026          case 2:
  1027              // string token
  1028              if (mEnd - mP < 4) return s;
  1029              len = ReadBinDWord();
  1030              if (mEnd - mP < int(len)) return s;
  1031              s = std::string(mP, len);
  1032              mP += (len + 2);
  1033              return s;
  1034          case 3:
  1035              // integer token
  1036              mP += 4;
  1037              return "<integer>";
  1038          case 5:
  1039              // GUID token
  1040              mP += 16;
  1041              return "<guid>";
  1042          case 6:
  1043              if (mEnd - mP < 4) return s;
  1044              len = ReadBinDWord();
  1045              mP += (len * 4);
  1046              return "<int_list>";
  1047          case 7:
  1048              if (mEnd - mP < 4) return s;
  1049              len = ReadBinDWord();
  1050              mP += (len * mBinaryFloatSize);
  1051              return "<flt_list>";
  1052          case 0x0a:
  1053              return "{";
  1054          case 0x0b:
  1055              return "}";
  1056          case 0x0c:
  1057              return "(";
  1058          case 0x0d:
  1059              return ")";
  1060          case 0x0e:
  1061              return "[";
  1062          case 0x0f:
  1063              return "]";
  1064          case 0x10:
  1065              return "<";
  1066          case 0x11:
  1067              return ">";
  1068          case 0x12:
  1069              return ".";
  1070          case 0x13:
  1071              return ",";
  1072          case 0x14:
  1073              return ";";
  1074          case 0x1f:
  1075              return "template";
  1076          case 0x28:
  1077              return "WORD";
  1078          case 0x29:
  1079              return "DWORD";
  1080          case 0x2a:
  1081              return "FLOAT";
  1082          case 0x2b:
  1083              return "DOUBLE";
  1084          case 0x2c:
  1085              return "CHAR";
  1086          case 0x2d:
  1087              return "UCHAR";
  1088          case 0x2e:
  1089              return "SWORD";
  1090          case 0x2f:
  1091              return "SDWORD";
  1092          case 0x30:
  1093              return "void";
  1094          case 0x31:
  1095              return "string";
  1096          case 0x32:
  1097              return "unicode";
  1098          case 0x33:
  1099              return "cstring";
  1100          case 0x34:
  1101              return "array";
  1102          }
  1103      }
  1104      // process text-formatted file
  1105      else {
  1106          FindNextNoneWhiteSpace();
  1107          if (mP >= mEnd)
  1108              return s;
  1109
  1110          while ((mP < mEnd) && !isspace((unsigned char)*mP)) {
  1111              // either keep token delimiters when already holding a token, or return if first valid char
  1112              if (*mP == ';' || *mP == '}' || *mP == '{' || *mP == ',') {
  1113                  if (!s.size())
  1114                      s.append(mP++, 1);
  1115                  break; // stop for delimiter
  1116              }
  1117              s.append(mP++, 1);
  1118          }
  1119      }
  1120      return s;
  1121  }
