  1124  void XFileParser::FindNextNoneWhiteSpace() {
  1125      if (mIsBinaryFormat)
  1126          return;
  1127
  1128      bool running = true;
  1129      while (running) {
  1130          while (mP < mEnd && isspace((unsigned char)*mP)) {
  1131              if (*mP == '\n')
  1132                  mLineNumber++;
  1133              ++mP;
  1134          }
  1135
  1136          if (mP >= mEnd)
  1137              return;
  1138
  1139          // check if this is a comment
  1140          if ((mP[0] == '/' && mP[1] == '/') || mP[0] == '#')
  1141              ReadUntilEndOfLine();
  1142          else
  1143              break;
  1144      }
  1145  }
