   112  // Imports the given file into the given scene structure.
   113  void XFileImporter::InternReadFile( const std::string& pFile, aiScene* pScene, IOSystem* pIOHandler) {
   114      // read file into memory
   115      std::unique_ptr<IOStream> file( pIOHandler->Open( pFile));
   116      if ( file.get() == nullptr ) {
   117          throw DeadlyImportError( "Failed to open file ", pFile, "." );
   118      }
   119
   120      static const size_t MinSize = 16;
   121      size_t fileSize = file->FileSize();
   122      if ( fileSize < MinSize ) {
   123          throw DeadlyImportError( "XFile is too small." );
   124      }
   125
   126      // in the hope that binary files will never start with a BOM ...
   127      mBuffer.resize( fileSize + 1);
   128      file->Read( &mBuffer.front(), 1, fileSize);
   129      ConvertToUTF8(mBuffer);
   130
   131      // parse the file into a temporary representation
   132      XFileParser parser( mBuffer);
   133
   134      // and create the proper return structures out of it
   135      CreateDataRepresentationFromImport( pScene, parser.GetImportedData());
   136
   137      // if nothing came from it, report it as error
   138      if ( !pScene->mRootNode ) {
   139          throw DeadlyImportError( "XFile is ill-formatted - no content imported." );
   140      }
   141  }
