   143  // ------------------------------------------------------------------------------------------------
   144  // Constructs the return data structure out of the imported data.
   145  void XFileImporter::CreateDataRepresentationFromImport( aiScene* pScene, XFile::Scene* pData)
   146  {
   147      // Read the global materials first so that meshes referring to them can find them later
   148      ConvertMaterials( pScene, pData->mGlobalMaterials);
   149
   150      // copy nodes, extracting meshes and materials on the way
   151      pScene->mRootNode = CreateNodes( pScene, nullptr, pData->mRootNode);
   152
   153      // extract animations
   154      CreateAnimations( pScene, pData);
   155
   156      // read the global meshes that were stored outside of any node
   157      if( !pData->mGlobalMeshes.empty() )  {
   158          // create a root node to hold them if there isn't any, yet
   159          if( pScene->mRootNode == nullptr ) {
   160              pScene->mRootNode = new aiNode;
   161              pScene->mRootNode->mName.Set( "$dummy_node");
   162          }
   163
   164          // convert all global meshes and store them in the root node.
   165          // If there was one before, the global meshes now suddenly have its transformation matrix...
   166          // Don't know what to do there, I don't want to insert another node under the present root node
   167          // just to avoid this.
   168          CreateMeshes( pScene, pScene->mRootNode, pData->mGlobalMeshes);
   169      }
   170
   171      if (!pScene->mRootNode) {
   172          throw DeadlyImportError( "No root node" );
   173      }
   174
   175      // Convert everything to OpenGL space... it's the same operation as the conversion back, so we can reuse the step directly
   176      MakeLeftHandedProcess convertProcess;
   177      convertProcess.Execute( pScene);
   178
   179      FlipWindingOrderProcess flipper;
   180      flipper.Execute(pScene);
   181
   182      // finally: create a dummy material if not material was imported
   183      if( pScene->mNumMaterials == 0) {
   184          pScene->mNumMaterials = 1;
   185          // create the Material
   186          aiMaterial* mat = new aiMaterial;
   187          int shadeMode = (int) aiShadingMode_Gouraud;
   188          mat->AddProperty<int>( &shadeMode, 1, AI_MATKEY_SHADING_MODEL);
   189          // material colours
   190          int specExp = 1;
   191
   192          aiColor3D clr = aiColor3D( 0, 0, 0);
   193          mat->AddProperty( &clr, 1, AI_MATKEY_COLOR_EMISSIVE);
   194          mat->AddProperty( &clr, 1, AI_MATKEY_COLOR_SPECULAR);
   195
   196          clr = aiColor3D( 0.5f, 0.5f, 0.5f);
   197          mat->AddProperty( &clr, 1, AI_MATKEY_COLOR_DIFFUSE);
   198          mat->AddProperty( &specExp, 1, AI_MATKEY_SHININESS);
   199
   200          pScene->mMaterials = new aiMaterial*[1];
   201          pScene->mMaterials[0] = mat;
   202      }
   203  }
